// 字节完全相同的重复提交（含无效 UTF-8 编号）仍是幂等的：
// 返回首次成功结果，不重新装卸。
func TestAdjustmentIdempotentWithInvalidUTF8(t *testing.T) {
	r := NewRegistry()
	if err := r.RegisterCompartment("C\x80", 100); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G\x80", 10, "X", true); err != nil {
