	got := []string{view.Cargo[0].ID, view.Cargo[1].ID, view.Cargo[2].ID}
	want := []string{"G1", "G2", "G3"}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("货物清单应按编号字典序排列: got=%v want=%v", got, want)
		}
	}
