	if err != nil {
		t.Fatal(err)
	}
	// 调用方修改返回内容。
	view.UsedWeight = 9999
	view.Cargo[0].Weight = 9999
	view.Cargo[0].ID = "HACKED"

	// 系统记录不受影响。
