8	// newReplaceRegistry 构造同舱更换目的地货物的初始配载：
9	// C1 承重 100；G1（20，上海，不允许混装）、G2（30，上海，不允许混装）
10	// 已装入 C1；G3（40，北京，混装许可由参数指定）尚未装载。
11	func newReplaceRegistry(t *testing.T, g3AllowMixed bool) *Registry {
12		t.Helper()
13		r := NewRegistry()
14		if err := r.RegisterCompartment("C1", 100); err != nil {
15			t.Fatal(err)
16		}
17		if err := r.RegisterCargo("G1", 20, "Shanghai", false); err != nil {
18			t.Fatal(err)
19		}
20		if err := r.RegisterCargo("G2", 30, "Shanghai", false); err != nil {
21			t.Fatal(err)
22		}
23		if err := r.RegisterCargo("G3", 40, "Beijing", g3AllowMixed); err != nil {
24			t.Fatal(err)
25		}
26		if _, err := r.Adjust("A0", []Op{
27			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
28			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
29		}); err != nil {
30			t.Fatal(err)
31		}
32		return r
33	}
