35	// assertReplaceProfilesUnchanged 核对三件货物登记的重量、目的地与混装许可
36	// 始终不变，仅归属随调整结果改变。
37	func assertReplaceProfilesUnchanged(t *testing.T, r *Registry, g3AllowMixed bool) {
38		t.Helper()
39		g1, _ := r.Cargo("G1")
40		if g1.Weight != 20 || g1.Destination != "Shanghai" || g1.AllowMixed {
41			t.Fatalf("G1 登记资料被改变: %+v", g1)
42		}
43		g2, _ := r.Cargo("G2")
44		if g2.Weight != 30 || g2.Destination != "Shanghai" || g2.AllowMixed {
45			t.Fatalf("G2 登记资料被改变: %+v", g2)
46		}
47		g3, _ := r.Cargo("G3")
48		if g3.Weight != 40 || g3.Destination != "Beijing" || g3.AllowMixed != g3AllowMixed {
49			t.Fatalf("G3 登记资料被改变: %+v", g3)
50		}
51	}
52	
53	// 同一次调整中卸下原目的地的 G1、G2 并装入新目的地的 G3：合法性以全部
54	// 操作完成后的最终配载判断，原货物尚未移出的临时共舱不算混装冲突。
55	// 装入写在卸货之前或之后，结论与最终查询结果都应一致。
56	func TestReplaceDestinationCargoSuccess(t *testing.T) {
57		for _, tc := range []struct {
58			name string
59			ops  []Op
60		}{
61			{
62				name: "先卸后装",
63				ops: []Op{
64					{Kind: OpUnload, CargoID: "G1"},
65					{Kind: OpUnload, CargoID: "G2"},
66					{Kind: OpLoad, CargoID: "G3", Target: "C1"},
67				},
68			},
69			{
70				name: "先装后卸",
71				ops: []Op{
72					{Kind: OpLoad, CargoID: "G3", Target: "C1"},
73					{Kind: OpUnload, CargoID: "G1"},
74					{Kind: OpUnload, CargoID: "G2"},
75				},
76			},
77		} {
78			t.Run(tc.name, func(t *testing.T) {
79				r := newReplaceRegistry(t, true)
80				res, err := r.Adjust("A1", tc.ops)
81				if err != nil {
82					t.Fatalf("原货物全部移出后只剩 G3，应成功: %v", err)
83				}
84				// 成功结果保留此次调整编号。
85				if res.ID != "A1" {
86					t.Fatalf("结果编号错误: %+v", res)
87				}
88				// 两件卸下、一件装入，货物变化按编号字典序排列。
89				if len(res.CargoChanges) != 3 {
90					t.Fatalf("应列出 3 条货物变化: %+v", res.CargoChanges)
91				}
92				wantChanges := []CargoChange{
93					{CargoID: "G1", From: "C1", To: ""},
94					{CargoID: "G2", From: "C1", To: ""},
95					{CargoID: "G3", From: "", To: "C1"},
96				}
97				for i, want := range wantChanges {
98					if res.CargoChanges[i] != want {
99						t.Fatalf("第 %d 条货物变化错误: got=%+v want=%+v", i, res.CargoChanges[i], want)
100					}
101				}
102				// C1 重量 50 -> 40。
103				if len(res.CompartmentChanges) != 1 {
104					t.Fatalf("应只列出 C1 的变化: %+v", res.CompartmentChanges)
105				}
106				cp := res.CompartmentChanges[0]
107				if cp.CompartmentID != "C1" || cp.WeightBefore != 50 || cp.WeightAfter != 40 {
108					t.Fatalf("C1 重量变化错误: %+v", cp)
109				}
110				// 查询：剩余 60，清单只含 G3。
111				cpt, _ := r.Compartment("C1")
112				if cpt.UsedWeight != 40 || cpt.RemainingWeight != 60 {
113					t.Fatalf("C1 重量错误: %+v", cpt)
114				}
115				if len(cpt.Cargo) != 1 || cpt.Cargo[0].ID != "G3" {
116					t.Fatalf("C1 清单应只含 G3: %+v", cpt.Cargo)
117				}
118				// 货物归属与舱位清单相互对应。
119				g3, _ := r.Cargo("G3")
120				if !g3.Loaded || g3.CompartmentID != "C1" {
121					t.Fatalf("G3 应已装入 C1: %+v", g3)
122				}
123				for _, id := range []string{"G1", "G2"} {
124					cv, _ := r.Cargo(id)
125					if cv.Loaded || cv.CompartmentID != "" {
126						t.Fatalf("%s 记录应保留且为未装载: %+v", id, cv)
127					}
128				}
129				assertReplaceProfilesUnchanged(t, r, true)
130			})
131		}
132	}
